// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address nonOwner) public {
        vm.assume(nonOwner != address(c));
        vm.assume(nonOwner != c.owner());
        vm.assume(amount <= type(uint256).max / 2);
        vm.assume(address(c).balance == 0);
        vm.deal(address(c), amount);
        vm.prank(c.owner());
        c.sendMoney(address(0), amount);
        vm.prank(nonOwner);
        bool ok = true;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
